// SECURE — catch errors, log internally, return generic message
app.get('/user/:id', async (req, res) => {
  try {
    const user = await db.users.findById(req.params.id);
    res.json(user);
  } catch (error) {
    // Log the full error internally for debugging
    logger.error({ err: error, userId: req.params.id }, 'Failed to fetch user');
    // Return nothing useful to the client
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Global error handler — catches any unhandled errors
app.use((err: Error, req: Request, res: Response, next: NextFunction) => {
  // Log full error (including stack trace) to your logging service
  logger.error({ err, url: req.url, method: req.method }, 'Unhandled error');

  // In development: show the error (useful for debugging)
  if (process.env.NODE_ENV === 'development') {
    return res.status(500).json({ error: err.message, stack: err.stack });
  }

  // In production: generic message only
  res.status(500).json({ error: 'Something went wrong' });
});

